"""Author the two planned-but-missing guesstimates (metro-ticketing-revenue,
coffee-sachets-daily). Every `result` is computed by evaluating its `expr`, so
the published arithmetic cannot drift from the published working.

Grounding (Placements folder casebooks):
- IIM Calcutta casebook, "Estimate Annual Revenue of Mumbai Local Train Network":
  key learnings "Behavioural segmentation (passes vs tickets) improves accuracy"
  and "convert monthly prices into per-use values". Its worked solution also
  multiplies daily trips by the monthly pass price, which the metro entry
  teaches as a trap (described, not attributed).
- IIM Ahmedabad prep book, Guesstimate 25 (Delhi Metro Yellow Line ridership
  from train capacity) -> the metro entry's supply-side triangulation.
- IIM Calcutta casebook, "Cup Noodles Sold per Day in India" (awareness ->
  trial -> repeat funnel, urban/rural split) and "Cups of Tea Consumed Daily":
  "Frequency of usage is more important than just user count";
  "In habit-based products, think in terms of occasions per day".
"""
import io, json, re

SAFE = re.compile(r"^[0-9.+\-*/() \t]+$")
def ev(expr):
    assert SAFE.match(expr), expr
    return eval(expr, {"__builtins__": {}}, {})

def line(i, label, expr, display, unit, carried, uses, so_what, prefix="c"):
    r = ev(expr)
    r = int(r) if abs(r - round(r)) < 1e-9 else round(r, 6)
    return {"id": f"{prefix}{i}", "label": label, "expr": expr, "display": display, "result": r,
            "tolerance": 0, "unit": unit, "carriedForward": carried, "uses": uses, "soWhat": so_what}

def A(id_, lever, value, numeric, unit, basis, defence, confidence, contested):
    return {"id": id_, "lever": lever, "value": value, "numeric": numeric, "unit": unit, "basis": basis,
            "defence": defence, "confidence": confidence, "contestedBy": contested}

