metro_calc = [
    line(1, "Riders on a working day", "20000000 * 0.08", "2 crore residents × 8%", "riders", "16 lakh riders",
         ["a-city-pop", "a-rider-share"],
         "The shakiest number in the tree, and every line below is linear in it. Box it, and argue about it once rather than on every line."),
    line(2, "Pass holders", "1600000 * 0.4", "16 lakh × 40%", "holders", "6.4 lakh holders", ["a-pass-share"],
         "People, not journeys. A monthly price is only ever multiplied by people."),
    line(3, "Pay-per-ride riders on a working day", "1600000 * 0.6", "16 lakh × 60%", "riders", "9.6 lakh riders", ["a-pass-share"],
         "The other 60%. They pay by the ride, so from here they are counted in journeys."),
    line(4, "Rides a pass holder takes in a month", "2 * 25", "2 journeys × 25 working days", "rides a month", "50 rides",
         ["a-pass-trips", "a-days-month"],
         "The denominator for the most important division in the question."),
    line(5, "What a pass holder pays per ride", "1000 / 50", "₹1,000 ÷ 50 rides", "₹ a ride", "₹20 a ride", ["a-pass-price"],
         "This is the move the question exists to test. A pass holder pays ₹20 a ride against ₹35 for a token — the heaviest users pay the least. Say it before you multiply anything, and the pass line cannot be double-counted."),
    line(6, "Pass revenue in a year", "640000 * 1000 * 12", "6.4 lakh holders × ₹1,000 × 12 months", "₹ a year", "₹768 crore",
         ["a-pass-price", "a-months"],
         "Annualised by months, because that is how a pass is bought. Multiplying by working days here would price each holder at ₹3 lakh a year."),
    line(7, "Pay-per-ride journeys on a working day", "960000 * 1.6", "9.6 lakh riders × 1.6 journeys", "journeys a day", "15.4 lakh journeys",
         ["a-ppr-trips"],
         "Together with the 12.8 lakh pass journeys this is 28.2 lakh journeys on a working day. Pass holders are 40% of the riders but 45% of the journeys."),
    line(8, "Working-day equivalents in a year", "300 + 65 * 0.55", "300 working days + 65 days × 55%", "day-equivalents", "335.75",
         ["a-work-days-year", "a-off-days", "a-off-factor"],
         "Weekends belong to the pay-per-ride line only. A pass holder's Sunday ride earns the network nothing extra."),
    line(9, "Pay-per-ride journeys in a year", "1536000 * 335.75", "15.36 lakh × 335.75", "journeys a year", "51.6 crore journeys", [],
         "Over half the year's journeys, and — as the next line shows — over two-thirds of its money."),
    line(10, "Pay-per-ride revenue in a year", "515712000 * 35", "51.6 crore journeys × ₹35", "₹ a year", "₹1,805 crore", ["a-fare"],
         "The larger line by far, and the only one the average fare touches."),
    line(11, "Total farebox in a year", "7680000000 + 18049920000", "₹768 crore passes + ₹1,805 crore pay-per-ride", "₹ a year", "₹2,573 crore", [],
         "Passes are 30% of the money on 45% of the working-day journeys. If your pass line came out with a larger share of revenue than of journeys, you priced it per trip."),
    line(12, "Total farebox in crore", "25729920000 / 10000000", "₹25,730 Mn ÷ 1 crore", "₹ crore a year", "≈ ₹2,500 crore — round it before you say it", [],
         "Say ₹2,500 crore. The rider share alone could move it by a quarter; four significant figures would claim a precision nothing above supports."),
]

