for d in (metro, coffee):
    io.open(f"content/guesstimates/{d['id']}.json", "w", encoding="utf-8").write(
        json.dumps(d, ensure_ascii=False, indent=2) + "\n")
    last = d["calculation"][-1]["result"]
    drift = abs(last - d["finalAnswerNumeric"]) / d["finalAnswerNumeric"]
    print(f"{d['id']}: {len(d['assumptions'])} assumptions, {len(d['calculation'])} calc + "
          f"{len(d['triangulation']['lines'])} triangulation lines; last line {last:,} vs "
          f"finalAnswerNumeric {d['finalAnswerNumeric']:,} ({drift*100:.1f}% apart); tabLabel {len(d['tabLabel'])} chars")
